import socketfrom lib.utility.util import chessboardfrom lib.classDir.class_file import pieces, has_played, ipclient_s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)while True:    client_s.sendto(bytes('toto', 'utf-8'), (ip, 12345))    data, addr = client_s.recvfrom(4096)    chessboard_received = eval(data)    chessboard = chessboard_received    print(chessboard)    data, addr = client_s.recvfrom(4096)    isit_true_false = bool(data.decode())    if isit_true_false == True:        client_s.close()    if pieces["king"][1].dead == 1:        chessboard_tosend = bytes(str(chessboard), 'utf-8')        true_false = bytes(str(True), 'utf-8')        client_s.sendto(chessboard_tosend, (ip, 12345))        client_s.sendto(true_false, (ip, 12345))        client_s.close()    else:        if has_played == True:            has_played = False            chessboard_tosend = bytes(str(chessboard), 'utf-8')            true_false = bytes(str(False), 'utf-8')            client_s.sendto(chessboard_tosend, (ip, 12345))            client_s.sendto(true_false, (ip, 12345))